import path from "node:path";

// Generated by Payload; ESLint and Prettier ignore them (see eslint.config.mjs and .prettierignore),
// and ESLint warns about explicitly passed ignored files, which `--max-warnings=0` turns into a failure.
const GENERATED = [
  /^payload-types\.ts$/,
  /^migrations\//,
  /^app\/\(payload\)\/admin\/importMap\.js$/,
];

const quote = (file) => JSON.stringify(file);
const authored = (files) =>
  files.filter((file) => {
    const relative = path.relative(process.cwd(), file).split(path.sep).join("/");
    return !GENERATED.some((pattern) => pattern.test(relative));
  });

/** Runs `command` on the hand-written files only. */
const onAuthored = (command) => (files) => {
  const list = authored(files);
  return list.length === 0 ? [] : [`${command} ${list.map(quote).join(" ")}`];
};

/** @type {import("lint-staged").Configuration} */
const config = {
  "*.{ts,tsx,mts}": (files) => [
    ...onAuthored("eslint --max-warnings=0 --fix")(files),
    ...onAuthored("prettier --write")(files),
    // tsc cannot check single files against the project config, so type-check the whole project once.
    "tsc --noEmit",
  ],
  "*.{js,mjs,cjs}": (files) => [
    ...onAuthored("eslint --max-warnings=0 --fix")(files),
    ...onAuthored("prettier --write")(files),
  ],
  "*.{json,md,css,yml,yaml}": ["prettier --write"],
};

export default config;
